Always sum and display the remainder of the population under a distinct `-other-` or `remainder` bucket.
```rust
fn process_profile_correct(samples: &[Sample]) {
    let mut counts = HashMap::new();
    let total_samples = samples.len();
    for s in samples {
        *counts.entry(s.function_name).or_insert(0) += 1;
    }
    let top_k = get_top_k(&counts, 5);
    let top_sum: usize = top_k.values().sum();
    display_top_k(top_k);
    println!("-other-: {} samples ({:.2}%)", total_samples - top_sum, (total_samples - top_sum) as f64 / total_samples as f64 * 100.0);
}
```
